const http = require('http');
const https = require('https');
const { URL } = require('url');
const net = require('net');

// Allowlist of trusted backend domains
const TRUSTED_BACKENDS = new Set([
  'api.example.com',
  'cdn.example.com',
  'auth.example.com',
  'internal.example.com'
]);

// Unicode normalization table for common confusables
const CONFUSABLE_MAP = {
  '\u0430': 'a', // Cyrillic а
  '\u0435': 'e', // Cyrillic е
  '\u043E': 'o', // Cyrillic о
  '\u0440': 'p', // Cyrillic р
  '\u0441': 'c', // Cyrillic с
  '\u0443': 'y', // Cyrillic у
  '\u0445': 'x', // Cyrillic х
  '\u0456': 'i', // Ukrainian і
  '\u0501': 'd', // Cyrillic ԁ
};

function normalizeHomoglyphs(input) {
  let result = '';
  for (let i = 0; i < input.length; i++) {
    const ch = input[i];
    result += CONFUSABLE_MAP[ch] || ch;
  }
  return result;
}

function isAsciiOnly(str) {
  for (let i = 0; i < str.length; i++) {
    if (str.charCodeAt(i) > 127) return false;
  }
  return true;
}

// Validate that a header name/value does not contain CR/LF (CWE-113)
function isValidHeaderToken(str) {
  return typeof str === 'string' && !/[\r\n]/.test(str);
}

async function validateDestination(hostname) {
  // Step 1: Check if hostname is pure ASCII
  if (isAsciiOnly(hostname)) {
    return TRUSTED_BACKENDS.has(hostname);
  }

  // Step 2: For non-ASCII, reject entirely
  // Only pure ASCII hostnames from the allowlist are permitted
  return false;
}

async function resolveAndConnect(hostname, port) {
  return new Promise((resolve, reject) => {
    const socket = net.createConnection({ host: hostname, port }, () => {
      resolve(socket);
    });
    socket.on('error', reject);
    socket.setTimeout(5000, () => {
      socket.destroy();
      reject(new Error('Connection timeout'));
    });
  });
}

async function handleProxyRequest(req, res) {
  try {
    const targetUrl = req.headers['x-proxy-target'];
    if (!targetUrl) {
      res.writeHead(400);
      res.end('Missing X-Proxy-Target header');
      return;
    }

    const parsed = new URL(targetUrl);
    const hostname = parsed.hostname;
    const port = parsed.port || (parsed.protocol === 'https:' ? 443 : 80);

    // Validate the destination
    const allowed = await validateDestination(hostname);
    if (!allowed) {
      res.writeHead(403);
      res.end('Destination not allowed');
      return;
    }

    // Connect to the validated destination
    const socket = await resolveAndConnect(hostname, port);

    // Forward the request. hostname is already validated against the allowlist
    // (pure ASCII, no CR/LF possible), so the Host header is safe.
    const requestLine = `${req.method} ${parsed.pathname}${parsed.search || ''} HTTP/1.1\r\n`;
    socket.write(requestLine);
    socket.write(`Host: ${hostname}\r\n`);
    socket.write('Connection: close\r\n');

    for (const [key, value] of Object.entries(req.headers)) {
      if (key === 'x-proxy-target' || key === 'host') continue;

      // Reject header names containing CR/LF (CWE-113)
      if (!isValidHeaderToken(key)) continue;

      // Header values may be strings or arrays (duplicate headers).
      const values = Array.isArray(value) ? value : [value];
      for (const v of values) {
        // Skip any value containing CR/LF to prevent header/request injection.
        if (!isValidHeaderToken(v)) continue;
        socket.write(`${key}: ${v}\r\n`);
      }
    }
    socket.write('\r\n');

    req.pipe(socket);
    socket.pipe(res);

    socket.on('error', () => {
      if (!res.headersSent) {
        res.writeHead(502);
        res.end('Backend connection error');
      }
    });
  } catch (err) {
    if (!res.headersSent) {
      res.writeHead(500);
      res.end('Internal proxy error');
    }
  }
}

const server = http.createServer(handleProxyRequest);
server.listen(8080, '127.0.0.1', () => {
  console.log('Proxy server listening on 127.0.0.1:8080');
});

module.exports = { validateDestination, normalizeHomoglyphs, TRUSTED_BACKENDS };
